sp_CriarItemPedido	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_CriarItemPedido`(\n\n    p_idPedido      INT,\n\n    p_idProduto     INT,\n\n    p_quantidade    INT,\n\n    p_valorUnitario DECIMAL(10,2),\n\n    p_desconto      DECIMAL(10,2),\n\n    p_valorTotal    DECIMAL(10,2)\n\n)\nBEGIN\n\n    INSERT INTO PedidoItem (idPedido, idProduto, quantidade, valorUnitario, desconto, valorTotal)\n\n    VALUES (p_idPedido, p_idProduto, p_quantidade, p_valorUnitario, p_desconto, p_valorTotal);\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
